use App\Models\ChildModel;
use Spatie\Tags\Tag;

// Function to consolidate all tags from child models and attach them to the parent model
function consolidateTagsToParent(ParentModel $parent)
{
    // Retrieve all child models associated with the parent
    $children = $parent->children; // Assuming 'children' is the relationship name

    // Initialize an empty collection to keep unique tags
    $allTags = collect();

    // Loop through each child model
    foreach ($children as $child) {
        // Retrieve tags for the current child model
