    if (file_exists($file_path)) {
        $data = file_get_contents($file_path);
        return json_decode($data, true);
    }
    return null;
}

// Function to write access information
function write_access_info($file_path, $data) {
    file_put_contents($file_path, json_encode($data));
}

// Get current visitor's IP and User-Agent
$current_ip = $_SERVER['REMOTE_ADDR'];
$current_user_agent = $_SERVER['HTTP_USER_AGENT'];

// Read stored access information
$access_info = read_access_info($file_path);

if ($access_info === null) {
    // If no device has accessed yet, store the current device's info
    $access_info = [
        'ip' => $current_ip,
        'user_agent' => $current_user_agent
    ];
    write_access_info($file_path, $access_info);
    echo "Access granted. You are the first visitor.";
} else {
    // Check if the current device matches the stored device
    if ($access_info['ip'] === $current_ip && $access_info['user_agent'] === $current_user_agent) {
        echo "Access granted. You are the authorized device.";
    } else {
        echo "Access denied. This URL can only be accessed by the first device.";
    }
}
?>
