$stmt->execute([$token]);
$record = $stmt->fetch();

if (!$record) {
    die('Invalid or expired token.');
}

$current_ip = $_SERVER['REMOTE_ADDR'];
$current_ua = $_SERVER['HTTP_USER_AGENT'];

// Check if this token has been used before
if (empty($record['device_info'])) {
