        'ip' => $current_ip,
        'user_agent' => $current_ua,
    ];
    $stmt = $db->prepare("UPDATE access_tokens SET device_info = ? WHERE token = ?");
    $stmt->execute([json_encode($device_info), $token]);
    // Also set a cookie to remember this device/browser
    setcookie("device_token", $token, time() + (10*365*24*60*60)); // 10 years
    echo "Welcome! Your session is now bound to this device.";
} else {
    // Already associated, check if current device matches
    $stored_device = json_decode($record['device_info'], true);

    if ($stored_device['ip'] !== $current_ip || $stored_device['user_agent'] !== $current_ua) {
        die('Access restricted to the original device.');
    }
    // Authorized device
    echo "Access granted.";
}
```

### Important considerations:
- Device fingerprinting (beyond IP and User-Agent) can improve precision but adds complexity.
- Trustworthiness depends on how strict or flexible you want constraints (perfect device binding may be hard).
- This method might be bypassed if users clear cookies/IP addresses, so combining multiple signals makes it more robust.
- Consider introducing additional security measures as needed.

