```jsx
import React, {useState, useCallback} from 'react';
import { FlatList, Text, TouchableOpacity } from 'react-native';

const MyItem = React.memo(({ item }) => (
  <TouchableOpacity>
    <Text>{item.name}</Text>
  </TouchableOpacity>
));

const MyFlatListComponent = () => {
  const [data, setData] = useState([
    { id: '1', name: 'Item 1' },
    { id: '2', name: 'Item 2' },
    { id: '3', name: 'Item 3' },
  ]);

  const updateItemName = useCallback((id, newName) => {
    setData(prevData => {
      const index = prevData.findIndex(item => item.id === id);
      if (index === -1) return prevData;

      const updatedItem = { ...prevData[index], name: newName };

      return [
        ...prevData.slice(0, index),
        updatedItem,
        ...prevData.slice(index + 1),
      ];
    });
  }, []);

  const handleItemPress = (id) => {
    updateItemName(id, 'Updated Name'); // Example update
  };

  const renderItem = ({ item }) => (
    <MyItem item={item} />
  );

  return (
    <FlatList
      data={data}
      keyExtractor={(item) => item.id}
      renderItem={renderItem}
    />
  );
};

export default MyFlatListComponent;
```

**Summary:**  
- Keep your data in state.  
- When updating an item, replace that item in your data array immutably.  
