Implement a corresponding property drawer:

```csharp
#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;

[CustomPropertyDrawer(typeof(ShowIfAttribute))]
public class ShowIfDrawer : PropertyDrawer
{
    public override float GetPropertyHeight(SerializedProperty property, GUIContent label)
    {
        ShowIfAttribute showIf = (ShowIfAttribute)attribute;
        SerializedProperty conditionProperty = property.serializedObject.FindProperty(showIf.conditionField);

        bool conditionMet = false;

        if (conditionProperty != null)
        {
            if (conditionProperty.propertyType == SerializedPropertyType.Enum)
            {
                int index = conditionProperty.enumValueIndex;
                conditionMet = index.ToString() == showIf.compareValue.ToString();
            }
        }

        return conditionMet ? EditorGUI.GetPropertyHeight(property, label, true) : 0f;
    }

    public override void OnGUI(Rect position, SerializedProperty property, GUIContent label)
    {
        ShowIfAttribute showIf = (ShowIfAttribute)attribute;
        SerializedProperty conditionProperty = property.serializedObject.FindProperty(showIf.conditionField);

        if (conditionProperty != null)
        {
            bool conditionMet = false;

            if (conditionProperty.propertyType == SerializedPropertyType.Enum)
            {
                int index = conditionProperty.enumValueIndex;
                conditionMet = index.ToString() == showIf.compareValue.ToString();
