```cpp
#include <iostream>
#include <vector>
#include <utility>

using namespace std;

// Function to plot the points using symmetry
void plotCirclePoints(int xc, int yc, int x, int y, vector<pair<int, int>>& points) {
    points.push_back(make_pair(xc + x, yc + y));
    points.push_back(make_pair(xc - x, yc + y));
    points.push_back(make_pair(xc + x, yc - y));
    points.push_back(make_pair(xc - x, yc - y));
    points.push_back(make_pair(xc + y, yc + x));
    points.push_back(make_pair(xc - y, yc + x));
    points.push_back(make_pair(xc + y, yc - x));
    points.push_back(make_pair(xc - y, yc - x));
}

// Bresenham's circle drawing algorithm
void bresenhamCircle(int xc, int yc, int r) {
    int x = 0, y = r;
    int d = 3 - 2 * r; // Initial decision variable

    vector<pair<int, int>> points; // To store the circle points

    while (x <= y) {
        plotCirclePoints(xc, yc, x, y, points); // Plot points in all octants

        if (d >= 0) {
            // Decision variable >= 0, choose diagonal
            y--;
            d = d + 4 * (x - y) + 10; // Update decision variable
        } else {
            // Decision variable < 0, choose horizontal
            d = d + 4 * x + 6; // Update decision variable
        }
        x++;
