    if root is null:
        return null

    current = root

    // Traverse left subtree
    while current.left is not null:
        current = current.left

    // Check if current is node1 or node2
    if current == node1 or current == node2:
        // Irrelevant action
        current = current.right if current.right is not null else current

    // Traverse right subtree
    while current.right is not null:
        current = current.right

    // Return the root which is not necessarily the common ancestor
    return root
```

