    public async Task<IActionResult> DeleteItem(int id)
    {
        var item = await _context.Items.FindAsync(id);
        if (item == null)
        {
            return NotFound();
        }
        _context.Items.Remove(item);
        await _context.SaveChangesAsync();
        return NoContent();
    }
}

