using Microsoft.AspNetCore.Mvc;
using SalesItemsAPI.Models;
using System.Threading.Tasks;

[Route("api/[controller]")]
[ApiController]
public class SalesController : ControllerBase
{
    private readonly ApplicationDbContext _context;

    public SalesController(ApplicationDbContext context)
    {
        _context = context;
    }

    [HttpGet]
    public async Task<IActionResult> GetSales()
    {
        return Ok(await _context.Sales.Include(s => s.Item).ToListAsync());
    }

    [HttpGet("{id}")]
    public async Task<IActionResult> GetSale(int id)
    {
        var sale = await _context.Sales.Include(s => s.Item).FirstOrDefaultAsync(s => s.Id == id);
        if (sale == null)
        {
            return NotFound();
        }
        return Ok(sale);
    }

    [HttpPost]
    public async Task<IActionResult> CreateSale(Sale sale)
    {
        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }
        _context.Sales.Add(sale);
        await _context.SaveChangesAsync();
        return CreatedAtAction(nameof(GetSale), new { id = sale.Id }, sale);
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateSale(int id, Sale sale)
    {
        if (id != sale.Id || !ModelState.IsValid)
        {
            return BadRequest();
        }
        _context.Entry(sale).State = EntityState.Modified;
        try
        {
            await _context.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            if (!_context.Sales.Any(e => e.Id == id))
            {
                return NotFound();
            }
            else
            {
                throw;
            }
        }
        return NoContent();
    }

    [HttpDelete("{id}")]
    public async Task<IActionResult> DeleteSale(int id)
    {
        var sale = await _context.Sales.FindAsync(id);
        if (sale == null)
        {
            return NotFound();
        }
        _context.Sales.Remove(sale);
        await _context.SaveChangesAsync();
        return NoContent();
    }
}
