**Controllers/SalesController.cs**
```csharp
using Microsoft.AspNetCore.Mvc;
using SalesItemsApi.Models;
using SalesItemsApi.Data;
using System.Collections.Generic;
using System.Linq;

namespace SalesItemsApi.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class SalesController : ControllerBase
    {
        [HttpGet]
        public ActionResult<IEnumerable<Sale>> GetSales()
        {
            return Ok(Repository.Sales);
        }

        [HttpGet("{id}")]
        public ActionResult<Sale> GetSale(int id)
        {
            var sale = Repository.Sales.FirstOrDefault(s => s.Id == id);
            if (sale == null)
                return NotFound();
            return Ok(sale);
        }

        [HttpPost]
        public ActionResult<Sale> CreateSale([FromBody] Sale sale)
        {
            // Validate ItemId exists
            var itemExists = Repository.Items.Any(i => i.Id == sale.ItemId);
            if (!itemExists)
                return BadRequest($"Item with ID {sale.ItemId} does not exist.");

            int newId = Repository.Sales.Any() ? Repository.Sales.Max(s => s.Id) + 1 : 1;
            sale.Id = newId;
            Repository.Sales.Add(sale);
            return CreatedAtAction(nameof(GetSale), new { id = sale.Id }, sale);
        }

        [HttpPut("{id}")]
        public IActionResult UpdateSale(int id, [FromBody] Sale updatedSale)
        {
            var existingSale = Repository.Sales.FirstOrDefault(s => s.Id == id);
            if (existingSale == null)
                return NotFound();

            // Validate ItemId exists
            var itemExists = Repository.Items.Any(i => i.Id == updatedSale.ItemId);
            if (!itemExists)
                return BadRequest($"Item with ID {updatedSale.ItemId} does not exist.");

            existingSale.ItemId = updatedSale.ItemId;
            existingSale.Quantity = updatedSale.Quantity;
            existingSale.Date = updatedSale.Date;
            return NoContent();
        }

        [HttpDelete("{id}")]
        public IActionResult DeleteSale(int id)
        {
            var sale = Repository.Sales.FirstOrDefault(s => s.Id == id);
            if (sale == null)
                return NotFound();

            Repository.Sales.Remove(sale);
            return NoContent();
        }
    }
}
